{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "A weighting parameter that linearly combines model-based and model-free Q-values to determine stage-1 action probabilities.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "An eligibility trace parameter that allows the stage-2 reward prediction error to update the stage-1 model-free Q-value of the chosen action.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay of Unchosen Options",
      "description": "The Q-values of the unchosen action at stage 1 and all unchosen state-action pairs at stage 2 decay towards zero at a constant rate.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] = (1 - decay) * q_stage1_mf[unchosen_1]\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] = (1 - decay) * q_stage2_mf[s, a]",
      "expressible_in_slots": true
    }
  ]
}
